-- Entity source: ats_parrent/services/application-service/src/main/java/fu/ats/entity/Application.java
-- Inherited columns: ats_parrent/services/application-service/src/main/java/fu/ats/entity/BaseAuditEntity.java
CREATE TABLE applications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    job_id UUID NOT NULL,
    candidate_id BIGINT NOT NULL,
    cv_id BIGINT,
    cv_url VARCHAR(2048) NOT NULL,
    department_id UUID,
    transferred_from BIGINT,
    pipeline_stage_id BIGINT NOT NULL,
    status VARCHAR(50) NOT NULL,
    applied_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by VARCHAR(100),
    updated_by VARCHAR(100),
    is_deleted BOOLEAN NOT NULL,
    CONSTRAINT pk_applications PRIMARY KEY (id),
    CONSTRAINT ck_applications_status CHECK (status IN ('SUBMITTED', 'IN_REVIEW', 'INTERVIEWING', 'OFFERED', 'HIRED', 'REJECTED', 'WITHDRAWN')),
    CONSTRAINT fk_applications_pipeline_stage_id FOREIGN KEY (pipeline_stage_id) REFERENCES pipeline_stages (id)
);

