CREATE TABLE interviews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    application_id BIGINT NOT NULL,
    interview_template_id BIGINT NOT NULL,
    interview_type VARCHAR(50) NOT NULL,
    scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL,
    meeting_link VARCHAR(1000),
    status VARCHAR(50) NOT NULL,
    duration_minutes INTEGER,
    feedback_text TEXT,
    score INTEGER,
    result VARCHAR(50),
    interviewer_name VARCHAR(255),
    interviewer_email VARCHAR(255),
    notes_file_path VARCHAR(1000),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by VARCHAR(100),
    updated_by VARCHAR(100),
    is_deleted BOOLEAN NOT NULL,
    CONSTRAINT pk_interviews PRIMARY KEY (id),
    CONSTRAINT ck_interviews_interview_type CHECK (interview_type IN ('PHONE', 'VIDEO', 'ONSITE', 'TECHNICAL', 'HR')),
    CONSTRAINT ck_interviews_status CHECK (status IN ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'NO_SHOW')),
    CONSTRAINT ck_interviews_result CHECK (result IN ('PENDING', 'PASS', 'FAIL')),
    CONSTRAINT fk_interviews_application_id FOREIGN KEY (application_id) REFERENCES applications (id),
    CONSTRAINT fk_interviews_interview_template_id FOREIGN KEY (interview_template_id) REFERENCES interview_templates (id)
);

